class BankTransactionException extends Exception {
    public BankTransactionException(String msg) { super(msg); }
    public BankTransactionException(String msg, Throwable cause) { super(msg, cause); }
}

public class CapstoneBankingDemo {
    public static void transfer(double balance, double amount) throws BankTransactionException {
        try {
            if (amount <= 0) throw new IllegalArgumentException("Amount must be positive");
            if (amount > balance) throw new IllegalStateException("Insufficient funds");
            System.out.println("Transfer completed: $" + amount);
        } catch (IllegalArgumentException | IllegalStateException e) {
            throw new BankTransactionException("Transaction failed: " + e.getMessage(), e);
        }
    }

    public static void main(String[] args) {
        try {
            transfer(100.0, 250.0);
        } catch (BankTransactionException e) {
            System.out.println("Handled: " + e.getMessage());
            System.out.println("Cause: " + e.getCause().getClass().getSimpleName());
        }
    }
}

