practiceProblems.solution:
public class BatchProcessor {
    public static void processBatch(int[] amounts) {
        int success = 0;
        int failed = 0;
        for (int amt : amounts) {
            try {
                if (amt <= 0) {
                    throw new IllegalArgumentException("Invalid amount: " + amt);
                }
                success++;
            } catch (IllegalArgumentException e) {
                failed++;
            }
        }
        System.out.println("Success: " + success + ", Failed: " + failed);
    }

    public static void main(String[] args) {
        int[] txs = {100, -20, 50, 0, 300};
        processBatch(txs);
    }
}

