class LowLevelStorageException extends Exception {
    public LowLevelStorageException(String msg) { super(msg); }
}

class OrderProcessingException extends Exception {
    public OrderProcessingException(String msg, Throwable cause) { super(msg, cause); }
}

public class MultiLevelTranslation {
    public static void daoSave() throws LowLevelStorageException {
        throw new LowLevelStorageException("Disk write I/O error");
    }

    public static void serviceProcess() throws OrderProcessingException {
        try {
            daoSave();
        } catch (LowLevelStorageException e) {
            throw new OrderProcessingException("Unable to place order", e);
        }
    }

    public static void main(String[] args) {
        try {
            serviceProcess();
        } catch (OrderProcessingException e) {
            System.out.println("Service Level: " + e.getMessage());
            System.out.println("Root Cause: " + e.getCause().getMessage());
        }
    }
}

