practiceProblems.solution:
public class SuppressionDemo {
    static class FailingResource implements AutoCloseable {
        public void doWork() throws Exception {
            throw new Exception("Primary Work Exception");
        }
        public void close() throws Exception {
            throw new Exception("Close Resource Exception");
        }
    }

    public static void main(String[] args) {
        try (FailingResource res = new FailingResource()) {
            res.doWork();
        } catch (Exception e) {
            System.out.println("Primary: " + e.getMessage());
            for (Throwable s : e.getSuppressed()) {
                System.out.println("Suppressed: " + s.getMessage());
            }
        }
    }
}

